svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg", svg = document.documentElement;
  var $ = function (id) { return document.getElementById(id); };
  var X0 = 60, K = 38, R = -2, P_QUESTION = 4, PMIN = 0.2, PMAX = 10;   // P = |1/HT| en δ
  var xde = function (P) { return X0 + K * P; };
  var nb = function (v) { var s = (Math.round(v * 100) / 100).toFixed(2).replace(/0$/, "").replace(/\.0$/, "").replace(".", ","); return s; };
  var sg = function (v) { return (v < 0 ? "−" : v > 0 ? "+" : "") + nb(Math.abs(v)); };

  // Graduations : 0 à −10 δ, et quelques distances
  var gr = $("graduations"), DIST = { 0: "∞", 1: "1 m", 2: "50 cm", 4: "25 cm", 5: "20", 10: "10 cm" };
  for (var P = 0; P <= 10; P++) {
    var x = xde(P);
    var l = document.createElementNS(NS, "line");
    l.setAttribute("x1", x); l.setAttribute("x2", x); l.setAttribute("y1", 146); l.setAttribute("y2", 154);
    l.setAttribute("stroke", "#8a93a3"); gr.appendChild(l);
    var t = document.createElementNS(NS, "text");
    t.setAttribute("x", x); t.setAttribute("y", 186); t.setAttribute("text-anchor", "middle"); t.setAttribute("class", "s");
    t.textContent = P === 0 ? "0" : "−" + P; gr.appendChild(t);
    if (DIST[P]) {
      var d = document.createElementNS(NS, "text");
      d.setAttribute("x", x); d.setAttribute("y", 204); d.setAttribute("text-anchor", "middle"); d.setAttribute("class", "s");
      d.setAttribute("style", "font-size:12px;fill:#7f8899"); d.textContent = DIST[P]; gr.appendChild(d);
    }
  }

  var Pcourant = P_QUESTION;
  function dessiner(P) {
    var x = xde(P);
    $("obj").setAttribute("x1", x); $("obj").setAttribute("x2", x);
    $("zone").setAttribute("x", x - 22); $("objt").setAttribute("x", x + 10);
    var d = 100 / P, acc = R + P;               // Acc = R − 1/HT, avec 1/HT = −P
    var dr = Math.round(d); $("l1").textContent = "HT " + (Math.abs(d - dr) < 0.05 ? "= −" : "≈ −") + dr + " cm → 1/HT = −" + nb(P) + " δ";
    if (acc >= 0) {
      $("crochet").setAttribute("visibility", "visible");
      $("crochetp").setAttribute("d", "M136 122 V116 H" + x.toFixed(1) + " V122");
      $("crochett").setAttribute("x", ((136 + x) / 2).toFixed(1));
      $("crochett").textContent = nb(acc) + " δ";
      $("l2").textContent = "Acc = R − 1/HT = −2 − (−" + nb(P) + ") = " + nb(acc) + " δ";
      $("res").textContent = acc < 0.05 ? "Au remotum : net sans accommoder" : "Il accommode de " + nb(acc) + " δ";
    } else {
      $("crochet").setAttribute("visibility", "hidden");
      $("l2").textContent = "Au-delà du remotum : même sans accommoder,";
      $("res").textContent = "l'image reste floue (myope non compensé)";
    }
  }

  // Glisser le texte
  var poignee = $("poignee"), actif = false;
  function versSVG(e) { var p = svg.createSVGPoint(); p.x = e.clientX; p.y = e.clientY; return p.matrixTransform(svg.getScreenCTM().inverse()); }
  poignee.addEventListener("pointerdown", function (e) { actif = true; $("aide").setAttribute("visibility", "hidden"); poignee.setPointerCapture(e.pointerId); e.preventDefault(); });
  poignee.addEventListener("pointermove", function (e) {
    if (!actif) return;
    Pcourant = Math.max(PMIN, Math.min(PMAX, (versSVG(e).x - X0) / K));
    dessiner(Pcourant);
  });
  function lacher() { if (actif) verifierDefi(); actif = false; }
  poignee.addEventListener("pointerup", lacher); poignee.addEventListener("pointercancel", lacher);
  poignee.addEventListener("lostpointercapture", lacher); document.addEventListener("pointerup", lacher);

  $("rejouer").addEventListener("click", function () { defi = -1; $("defi").setAttribute("visibility", "hidden"); Pcourant = P_QUESTION; dessiner(Pcourant); });

  // Défi : placer le texte pour obtenir une accommodation donnée (tolérance 0,3 δ)
  var DEFIS = [
    { texte: "il accommode de 1 δ", P: 3 },
    { texte: "il accommode de 5 δ", P: 7 },
    { texte: "il voit net sans accommoder", P: 2 }
  ];
  var defi = -1;
  function afficherDefi() {
    $("defi").setAttribute("visibility", "visible"); $("defifond").setAttribute("stroke", "#d9b26f");
    $("defi1").textContent = "🎯 Défi " + (defi + 1) + "/3 : place T pour que"; $("defi2").textContent = DEFIS[defi].texte;
  }
  function verifierDefi() {
    if (defi < 0) return;
    if (Math.abs(Pcourant - DEFIS[defi].P) > 0.3) return;
    Pcourant = DEFIS[defi].P; dessiner(Pcourant);
    $("defifond").setAttribute("stroke", "#5fd08a"); $("defi1").textContent = "✓ Bravo ! T à " + nb(100 / Pcourant) + " cm";
    var fini = defi === DEFIS.length - 1, suivant = defi + 1;
    $("defi2").textContent = fini ? "Tous les défis sont réussis 🎉" : "Défi suivant dans un instant…";
    defi = fini ? -1 : -2;
    if (!fini) setTimeout(function () { defi = suivant; afficherDefi(); }, 1600);
  }
  $("bdefi").addEventListener("click", function () { defi = 0; afficherDefi(); $("aide").setAttribute("visibility", "visible"); });

  // Réponse fausse de l'élève (position dans q.choix : 0 δ, 2 δ, 4 δ, 6 δ)
  var ERREURS = {
    0: { acc: 0, val: "0 δ", pourquoi: "→ 0 δ seulement si le texte est au remotum (50 cm)." },
    2: { acc: 4, val: "4 δ", pourquoi: "→ 4 δ = 1/0,25 : c'est oublier que R = −2 δ." },
    3: { acc: 6, val: "6 δ", pourquoi: "→ 6 δ : erreur de signe, R d'un myope est négatif." }
  };
  var m = /faux=(\d)/.exec(location.hash), err = m && ERREURS[m[1]];
  if (err) {
    svg.setAttribute("viewBox", "0 0 480 450");
    var xt = xde(P_QUESTION), xf = Math.max(14, xt - K * err.acc);   // où l'élève a mis, sans le dire, le remotum
    $("errp").setAttribute("d", err.acc ? "M" + xt + " 214 V220 H" + xf + " V214" : "M" + (xt - 8) + " 214 H" + (xt + 8));
    $("errt").setAttribute("x", err.acc ? Math.max(48, (xt + xf) / 2) : xt);
    $("errt").setAttribute("y", 236);
    $("l1").setAttribute("visibility", "hidden"); $("aide").setAttribute("visibility", "hidden");
    $("errval").textContent = err.val; $("errpourquoi").textContent = err.pourquoi;
    $("errcrochet").setAttribute("visibility", "visible"); $("erreur").setAttribute("visibility", "visible");
  }
  dessiner(Pcourant);
})();
